FUNCTION_BLOCK FB_S06
VAR_INPUT
    TempPV : REAL;
    SetTemp : REAL;
    Segment : INT;
    LoadReduceReq : BOOL;
END_VAR
VAR_OUTPUT
    HeatOn : BOOL;
    FanOn : BOOL;
    OverTempAlarm : BOOL;
    LoadReduce : BOOL;
    Status : WORD;
END_VAR
VAR
    InitDone : BOOL;
    InvalidSeg : BOOL;
    PrevInvalidSeg : BOOL;
    EffectiveSetTemp : REAL;
    HeatDemand : BOOL;
END_VAR

(* 语义冲突保留：K3/K1 要求按当前段目标值（SetTemp 经 0.5/0.8/1.0 缩放）做 +10/-3 ℃ 迟滞；
   LTL C7 原文写 TempPV <= SetTemp - 3.0。若 Segment<>2，按原始 SetTemp 与按当前段目标值会不一致。
   本实现按 K3/K1 使用 EffectiveSetTemp 的 -3.0 ℃ 迟滞；不新增外部接口。 *)

InvalidSeg := (Segment < 0) OR (Segment > 2);

IF NOT InitDone THEN
    HeatOn := FALSE;
    FanOn := FALSE;
    OverTempAlarm := FALSE;
    LoadReduce := FALSE;
    Status := WORD#16#0000;
    PrevInvalidSeg := InvalidSeg;
    InitDone := TRUE;
ELSE
    (* K1：段号 0/1/2 -> 50%/80%/100%；非法段按 0 段处理。 *)
    IF InvalidSeg THEN
        EffectiveSetTemp := SetTemp * 0.5;
    ELSE
        CASE Segment OF
            0: EffectiveSetTemp := SetTemp * 0.5;
            1: EffectiveSetTemp := SetTemp * 0.8;
            2: EffectiveSetTemp := SetTemp * 1.0;
        ELSE
            EffectiveSetTemp := SetTemp * 0.5;
        END_CASE;
    END_IF;

    (* K3/C7：超温报警迟滞。 *)
    IF TempPV > (EffectiveSetTemp + 10.0) THEN
        OverTempAlarm := TRUE;
    END_IF;

    IF OverTempAlarm AND (TempPV <= (EffectiveSetTemp - 3.0)) THEN
        OverTempAlarm := FALSE;
    END_IF;

    (* 上位机降载请求与超温降载合并；C1/C4 由 HeatDemand 强制关断保证。 *)
    LoadReduce := OverTempAlarm OR LoadReduceReq;

    (* K2：±5 ℃ 死区，区间内保持上一周期 HeatOn。 *)
    IF LoadReduce THEN
        HeatDemand := FALSE;
    ELSE
        IF TempPV < (EffectiveSetTemp - 5.0) THEN
            HeatDemand := TRUE;
        ELSIF TempPV > (EffectiveSetTemp + 5.0) THEN
            HeatDemand := FALSE;
        ELSE
            HeatDemand := HeatOn;
        END_IF;
    END_IF;

    (* K4/C2：HeatOn 为 TRUE 时 FanOn 必须为 TRUE；降载/超温时保持风机散热。 *)
    IF HeatDemand OR LoadReduce OR OverTempAlarm THEN
        FanOn := TRUE;
    ELSE
        FanOn := FALSE;
    END_IF;

    HeatOn := HeatDemand;

    (* Status：非法段优先，C8 对非法段状态保持到下一周期。 *)
    IF InvalidSeg OR PrevInvalidSeg THEN
        Status := WORD#16#8601;
    ELSIF LoadReduce OR OverTempAlarm THEN
        Status := WORD#16#8602;
    ELSE
        Status := WORD#16#0000;
    END_IF;

    PrevInvalidSeg := InvalidSeg;
END_IF;
END_FUNCTION_BLOCK
